cd /home/vscode/nullness-benchmarks/wala-util && sed -i '144,149s/return predecessors.getRelated(nodeManager.getNumber(node));/IntSet x = predecessors.getRelated(nodeManager.getNumber(node));
    if (x == null) {
      return EmptyIntSet.instance;
    } else {
      return x;
    }/' src/main/java/com/ibm/wala/util/graph/impl/SparseNumberedEdgeManager.java && ./gradlew compileJava -x test -q > new_build_output.log 2>&1
